package com.lazarokaua.dividaAPI.controller;import java.net.URI;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.DeleteMapping;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PathVariable;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.PutMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import org.springframework.web.servlet.support.ServletUriComponentsBuilder;import com.lazarokaua.dividaAPI.domain.divida.DividaDTO;import com.lazarokaua.dividaAPI.domain.divida.DividaResponse;import com.lazarokaua.dividaAPI.domain.divida.service.DividaService;import jakarta.validation.Valid;@RestController@RequestMapping("/dividas")public class DividaController {    private final DividaService dividaService;    public DividaController(DividaService dividaService) {        this.dividaService = dividaService;    }    @PostMapping     public ResponseEntity<DividaResponse> createDivida(@Valid @RequestBody DividaDTO dividaDTO) {        DividaResponse response = dividaService.criar(dividaDTO);        URI uri = ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(response.id()).toUri();        return ResponseEntity.created(uri).body(response);    }    @GetMapping    public ResponseEntity<Page<DividaDTO>> listAllDivida(Pageable pageable) {        return ResponseEntity.ok(dividaService.listarTodasAsDividas(pageable));    }    @GetMapping("/{id}")    public ResponseEntity<DividaDTO> listSpecifDivida(@PathVariable Long id) {        return ResponseEntity.ok(dividaService.buscarPorId(id));    }    @GetMapping("/buscarPorCpf/{cpf}")    public ResponseEntity<Page<DividaDTO>> listSpecifDivida(@PathVariable String cpf, Pageable pageable) {        return ResponseEntity.ok(dividaService.encontrarPorCpf(cpf, pageable));    }    @PutMapping("/{id}")    public ResponseEntity<DividaResponse> atualizarDivida(@PathVariable Long id, @RequestBody DividaDTO dividaDTO) {        DividaResponse dividaResponse = dividaService.atualizarDivida(id, dividaDTO);        return ResponseEntity.ok(dividaResponse);    }    @DeleteMapping("/{id}")    public ResponseEntity<Void> deletarDivida(@PathVariable Long id) {        dividaService.deletarDivida(id);        return ResponseEntity.noContent().build();    }}